WITH piligrim_dest_list AS ( SELECT DISTINCT dest_id FROM ( /* Old List (107 Cities) */ -- VALUES -- (70346),(808),(83409),(216354),(1585),(217362),(975),(759),(216346),(65815), -- (247),(307614),(289873),(76480),(204358),(298723),(82558),(75103),(517), -- (265316),(231),(1529),(879),(217335),(1242),(71642),(93968),(74124),(142), -- (636),(1136),(520),(669),(1061),(77167),(275),(69526),(802),(196),(1528), -- (77530),(200347),(305974),(68747),(735),(84848),(197504),(216551),(68705), -- (1343),(80438),(427),(77687),(73533),(196096),(202212),(711),(78796),(489), -- (747),(93580),(466),(77705),(68871),(1148),(1459),(361),(471),(70983), -- (81826),(501),(987),(93189),(76187),(196752),(84832),(74690),(1219), -- (94515),(1007),(65805),(496),(194482),(94509),(198868),(842),(69475), -- (74130),(215191),(84310),(1496),(403),(1141),(189),(133),(177),(1351), -- (70628),(74708),(66007),(198750),(663),(94877),(71756),(1128),(293),(534), -- (77093),(154),(1001),(70030),(576),(70429),(217),(960),(196420),(134), -- (205655),(94782),(300439) /* New List (120 Cities) */ VALUES (70346),(808),(83409),(216354),(1585),(217362),(975),(759),(216346),(65815),(247), (307614),(289873),(76480),(204358),(298723),(82558),(75103),(517),(265316),(231), (1529),(879),(217335),(1242),(71642),(93968),(74124),(142),(636),(1136),(520),(669), (1061),(77167),(275),(69526),(802),(196),(1528),(77530),(200347),(305974),(68747), (735),(84848),(197504),(216551),(68705),(1343),(80438),(427),(77687),(73533),(196096), (202212),(711),(78796),(489),(747),(93580),(466),(77705),(68871),(1148),(1459),(361), (471),(70983),(81826),(501),(987),(93189),(76187),(196752),(84832),(74690),(1219), (94515),(1007),(65805),(496),(194482),(94509),(198868),(842),(69475),(74130),(215191), (84310),(1496),(403),(1141),(189),(133),(177),(1351),(70628),(74708),(66007),(198750), (663),(94877),(71756),(1128),(293),(534),(77093),(154),(1001),(70030),(576),(70429), (217),(960),(196420),(94782),(300439) ) AS x(dest_id) ), /* ------------------------------------------------------------ 1. Base successful bookings for pilgrims -------------------------------------------------------------*/ base_users AS ( SELECT DISTINCT __time AS basedate, rb_user_id, src_id AS base_src_id, dest_id AS base_dest_id FROM user_interaction.confirm_order_details WHERE __time >= TIMESTAMP '2026-01-01 00:00:00' AND __time < TIMESTAMP '2026-02-01 00:00:00' AND status_str = 'SUCCESS' AND channel = 'MOBILE_APP' AND os = 'Android' AND country = 'IND' AND tin IS NOT NULL AND dest_id NOT IN (SELECT dest_id FROM piligrim_dest_list) ), /* ------------------------------------------------------------ 2. All post-booking searches for these users -------------------------------------------------------------*/ all_post_search AS ( SELECT b.rb_user_id, b.base_src_id, b.base_dest_id, b.basedate, s.src_id AS search_src_id, s.dest_id AS search_dest_id, s.__time AS searchdate, -- case -- when contains(channel_exp_info, 'RTR_SRP_AB:V0') then 'V0' -- when contains(channel_exp_info, 'RTR_SRP_AB:V1') then 'V1' -- when contains(channel_exp_info, 'RTR_SRP_AB:V2') then 'V2' -- else null -- end as rtr_variant -- , CASE WHEN s.__time IS NULL THEN 'Not Returned' WHEN date_diff('day', b.basedate, s.__time) = 0 THEN 'D+0' WHEN date_diff('day', b.basedate, s.__time) = 1 THEN 'D+1' WHEN date_diff('day', b.basedate, s.__time) = 2 THEN 'D+2' WHEN date_diff('day', b.basedate, s.__time) = 3 THEN 'D+3' WHEN date_diff('day', b.basedate, s.__time) = 4 THEN 'D+4' WHEN date_diff('day', b.basedate, s.__time) > 4 THEN 'D+5+' ELSE 'OtherDays' END AS Returntype -- 'Overall' AS Returntype FROM base_users b LEFT JOIN user_interaction.search_details s ON s.rb_user_id = b.rb_user_id AND __time >= TIMESTAMP '2026-01-01 00:00:00' AND s.__time > b.basedate AND s.__time < TIMESTAMP '2026-03-01 00:00:00' AND s.os = 'Android' AND s.country = 'IND' ), /* ------------------------------------------------------------ 3. All confirmed bookings in Nov 2025 (for return matching) -------------------------------------------------------------*/ return_confirm AS ( SELECT DISTINCT rb_user_id, src_id, dest_id FROM user_interaction.confirm_order_details WHERE __time >= TIMESTAMP '2026-01-01 00:00:00' AND __time < TIMESTAMP '2026-03-01 00:00:00' AND status_str = 'SUCCESS' AND channel = 'MOBILE_APP' AND os = 'Android' AND country = 'IND' ) SELECT -- rtr_variant, Returntype, /* Base Users */ COUNT(DISTINCT b.rb_user_id) AS base_users, /* A: Any search */ COUNT(DISTINCT CASE WHEN a.searchdate IS NOT NULL THEN a.rb_user_id END) AS any_sd_searched_users, /* B: exact return route search (D→S) */ COUNT(DISTINCT CASE WHEN a.search_src_id = a.base_dest_id AND a.search_dest_id = a.base_src_id THEN a.rb_user_id END ) AS return_route_searched_users, /* C: D → pilgrim destination X (X ≠ base_src_id) */ COUNT(DISTINCT CASE WHEN a.search_src_id = a.base_dest_id AND pd1.dest_id = a.search_dest_id AND a.search_dest_id <> a.base_src_id THEN a.rb_user_id END ) AS piligrim_searched_users, /* D: D → non-pilgrim */ -- COUNT(DISTINCT CASE -- WHEN a.search_src_id = a.base_dest_id -- AND pd1.dest_id IS NULL -- THEN a.rb_user_id END -- ) AS non_piligrim_searched_users, /* E: neither src nor dest in pilgrim list */ COUNT(DISTINCT CASE WHEN pd2.dest_id IS NULL AND pd1.dest_id IS NULL THEN a.rb_user_id END ) AS other_sd_searched_users, /* --- Confirmed versions --- */ COUNT(DISTINCT CASE WHEN rc.rb_user_id IS NOT NULL THEN a.rb_user_id END) AS any_sd_confirmed_users, COUNT(DISTINCT CASE WHEN a.search_src_id = a.base_dest_id AND a.search_dest_id = a.base_src_id AND rc.rb_user_id IS NOT NULL THEN a.rb_user_id END ) AS return_route_confirmed_users, COUNT(DISTINCT CASE WHEN a.search_src_id = a.base_dest_id AND pd1.dest_id = a.search_dest_id AND a.search_dest_id <> a.base_src_id AND rc.rb_user_id IS NOT NULL THEN a.rb_user_id END ) AS piligrim_confirmed_users, -- COUNT(DISTINCT CASE -- WHEN a.search_src_id = a.base_dest_id -- AND pd1.dest_id IS NULL -- AND rc.rb_user_id IS NOT NULL -- THEN a.rb_user_id END -- ) AS non_piligrim_confirmed_users, COUNT(DISTINCT CASE WHEN pd2.dest_id IS NULL AND pd1.dest_id IS NULL AND rc.rb_user_id IS NOT NULL THEN a.rb_user_id END ) AS other_sd_confirmed_users FROM all_post_search a JOIN base_users b ON a.rb_user_id = b.rb_user_id LEFT JOIN return_confirm rc ON a.rb_user_id = rc.rb_user_id AND a.search_src_id = rc.src_id AND a.search_dest_id = rc.dest_id /* Pre-joined pilgrim lists for speed */ LEFT JOIN piligrim_dest_list pd1 ON a.search_dest_id = pd1.dest_id LEFT JOIN piligrim_dest_list pd2 ON a.search_src_id = pd2.dest_id GROUP BY 1 ORDER BY 1;
